import re
from datetime import datetime

_DIGITS = "0123456789"
_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"[0-9]{5}-[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _field(row, key):
    value = row.get(key)
    return "" if value is None else str(value)


def _is_digits(s):
    return s != "" and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    """Return the normalized valid email, or None if invalid."""
    s = raw.strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()

    if s.count("@") != 1:
        return None
    local, domain = s.split("@")

    if domain in ("gmail.com", "googlemail.com"):
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        domain = "gmail.com"

    if not local:
        return None
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None
    return f"{local}@{domain}"


def _normalize_phone(raw):
    """Return the normalized valid 10-digit phone, or None if invalid."""
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in _DIGITS)

    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]

    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return None


def _normalize_zip(raw):
    s = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(s):
        s = s.split("-", 1)[0]
    if len(s) == 4 and _is_digits(s):
        s = "0" + s
    if len(s) == 5 and _is_digits(s):
        return s
    return ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    # Unparseable values sort as oldest.
    return datetime.min


def _is_opted_out(raw):
    return raw.strip().lower() in ("y", "yes", "true", "1")


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def dedupe_contacts(rows):
    # Normalize every row; drop rows with neither a valid email nor phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(_field(row, "email"))
        phone = _normalize_phone(_field(row, "phone"))
        if email is None and phone is None:
            continue
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(_field(row, "first_name")),
            "last_name": _normalize_name(_field(row, "last_name")),
            "zip": _normalize_zip(_field(row, "zip")),
            "email": email or "",
            "phone": phone or "",
            "source": _field(row, "source").strip().lower(),
            "tags": _parse_tags(_field(row, "tags")),
            "opted_out": _is_opted_out(_field(row, "opted_out")),
            "updated": _parse_updated(_field(row, "updated")),
        })

    # Union-find so matching is transitive.
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Collect groups; order by earliest input row.
    groups = {}
    order = []
    for i in range(len(recs)):
        root = find(i)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(recs[i])

    def best(members, field):
        """Pick the preferred row for a field: manual source, then latest
        updated, then earliest input row. Only rows with a non-empty value
        for the field qualify. Returns None if no row qualifies."""
        candidates = [m for m in members if m[field]]
        if not candidates:
            return None
        return max(
            candidates,
            key=lambda m: (m["source"] == "manual", m["updated"], -m["idx"]),
        )

    def value(members, field):
        chosen = best(members, field)
        return chosen[field] if chosen else ""

    people = []
    for root in order:
        members = groups[root]

        tags = set()
        for m in members:
            tags |= m["tags"]

        latest = max(m["updated"] for m in members)

        people.append({
            "first_name": value(members, "first_name"),
            "last_name": value(members, "last_name"),
            "zip": value(members, "zip"),
            "email": value(members, "email"),
            "phone": value(members, "phone"),
            "source": value(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": f"{latest.year:04d}-{latest.month:02d}-{latest.day:02d}",
        })

    return people
